  "content": "<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Notification settings</title>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      rel="stylesheet"
      href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400..700;1,400..700&family=Source+Sans+3:wght@300..900&family=JetBrains+Mono:wght@400;500;600&display=swap"
    />
    <link rel="stylesheet" href="node_modules/@taproot-ds/tokens/dist/css/tokens.css" />
    <link rel="stylesheet" href="node_modules/@taproot-ds/tokens/dist/css/base.css" />
    <style>
      main {
        max-width: 36rem;
        margin: 0 auto;
        padding: var(--ds-primitives-space-8) var(--ds-primitives-space-4);
      }
      .panel {
        display: flex;
        flex-direction: column;
        gap: var(--ds-primitives-space-6);
        padding: var(--ds-primitives-space-6);
        background: var(--ds-semantic-color-background-surface);
        border: 1px solid var(--ds-semantic-color-border-subtle);
        border-radius: var(--ds-semantic-radius-surface);
      }
      .panel h2 {
        margin: 0;
      }
    </style>
    <script type="module">
      import { defineSwitch } from "./node_modules/@taproot-ds/web-components/src/switch.js";
      import { defineSlider } from "./node_modules/@taproot-ds/web-components/src/slider.js";

      defineSwitch();
      defineSlider();

      const STORAGE_KEY = "notification-settings";

      function load() {
        try {
          return JSON.parse(localStorage.getItem(STORAGE_KEY)) ?? {};
        } catch {
          return {};
        }
      }

      function save(settings) {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
      }

      const settings = load();
      const emailSwitch = document.getElementById("email-notifications");
      const pushSwitch = document.getElementById("push-notifications");
      const volumeSlider = document.getElementById("notification-volume");

      // Restore saved state (programmatic changes fire no events).
      if (typeof settings.email === "boolean") emailSwitch.checked = settings.email;
      if (typeof settings.push === "boolean") pushSwitch.checked = settings.push;
      if (typeof settings.volume === "number") volumeSlider.value = settings.volume;

      // Each change applies immediately; there is no save button.
      function applySwitch(control, key) {
        control.addEventListener("change", () => {
          const previous = settings[key];
          settings[key] = control.checked;
          try {
            save(settings);
            control.removeAttribute("error");
          } catch {
            settings[key] = previous;
            control.checked = !control.checked;
            control.setAttribute("error", "Couldn't save this setting. Try again.");
          }
        });
      }

      applySwitch(emailSwitch, "email");
      applySwitch(pushSwitch, "push");

      volumeSlider.addEventListener("change", () => {
        const previous = settings.volume;
        settings.volume = volumeSlider.value;
        try {
          save(settings);
          volumeSlider.removeAttribute("error");
        } catch {
          settings.volume = previous;
          volumeSlider.setAttribute("error", "Couldn't save the volume. Try again.");
        }
      });
    </script>
  </head>
  <body>
    <main>
      <h1>Settings</h1>
      <section class="panel" aria-labelledby="notifications-heading">
        <h2 id="notifications-heading">Notifications</h2>
        <ds-switch
          id="email-notifications"
          label="Email notifications"
          hint="Get updates sent to your email address."
          checked
        ></ds-switch>
        <ds-switch
          id="push-notifications"
          label="Push notifications"
          hint="Get alerts on this device."
        ></ds-switch>
        <ds-slider
          id="notification-volume"
          label="Notification sound volume (%)"
          min="0"
          max="100"
          step="1"
          value="70"
        ></ds-slider>
      </section>
    </main>
  </body>
</html>
